// Writes demo/examples.html: a gallery of examples, each in a Preview / Code
// box (JsonDeck.example). The Code tab shows a complete HTML page generated by
// the library from the same config, so pasting it into an empty file works.
// Run: node scripts/make-examples.mjs
import { writeFileSync } from "node:fs"
import { accounts, dns, ec2, findings } from "./demo-data.mjs"

const few = (rows, n) => rows.slice(0, n)
const relEc2 = few(ec2, 6)
const relIds = new Set(relEc2.map((e) => e.instance_id))
const relFindings = findings.filter((f) => relIds.has(f.instance_id)).slice(0, 10)

